/// <summary>
/// Extension class for <c>InventTransferLine</c> table
/// </summary>
[ExtensionOf(tablestr(InventTransferLine))]
public final class METInventTransferLine_Extension
{
}

Method.Source:
    /// <summary>
    /// CB754 update underbond based on values of Item
    /// </summary>
    /// <param name = "_dropEstimated">_dropEstimated</param>
    public void insert(NoYes _dropEstimated)
    {
        next insert(_dropEstimated);

        // VM - CB754 - Excise Register start
        InventTransferTable inventTransferTable;
        METInventTransferTableExt metInventTransferTable;

        select firstonly UnderBond from metInventTransferTable
             join RecId, InventLocationIdTo from inventTransferTable
                where metInventTransferTable.InventTransferTable == inventTransferTable.RecId
                        && inventTransferTable.TransferId == this.TransferId;

        if (!metInventTransferTable.UnderBond)
        {
            METInventTable metInventTable;
            metTariffItemCodeBase metTariffItemCodeBase;

            select firstonly METTariffItemCodeBaseRecid from metInventTable
                where metInventTable.ItemId == this.ItemId
                exists join metTariffItemCodeBase
                where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid;

            if (metInventTable.RecId)
            {
                ttsbegin;
                metInventTransferTable.selectForUpdate(true);
                metInventTransferTable.UnderBond = NoYes::Yes;
                metInventTransferTable.InternalCustomer = inventTransferTable.InventLocationIdTo;
                metInventTransferTable.update();
                ttscommit;
            }
        }
        // VM - CB754 - Excise Register end
    }

/// <summary>
/// Get the warehouse category.
/// </summary>
/// <returns>Warehouse category</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METFilterCodeone displayMETFilterCodeOne()
{
    return InventTable::metGetFilterCodeOne(this.ItemId, this.inventDim().InventSiteId);
}

    /// <summary>
    ///    Called by the kernel when a field on the table has its value modified.
    /// </summary>
    /// <param name="_fieldId">
    ///    The field ID of the field that changed.
    /// </param>
    /// <remarks>
    ///    Methods that should be called when a field value changes are called in this method.
    /// </remarks>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(InventTransferLine, ItemId):
            case fieldNum(InventTransferLine, UnitId):
            case fieldNum(InventTransferLine, InventDimId):
                this.metInventTransferLine().updateUnitFields();
                break;
                
        }
    }

    /// <summary>
    /// Get order extract status
    /// </summary>
    /// <returns>METOrderExtractStatus</returns>
    public display METOrderExtractStatus displayOrderExtractStatus()
    {
        METInventTransferLine       metInventTransferLine;

        select firstonly OrderExtractStatus from metInventTransferLine
            where metInventTransferLine.InventTransferLine == this.RecId;

        return metInventTransferLine.OrderExtractStatus;
    }

    /// <summary>
    /// Updates the InventTransferLine and related METInventTransferLine fields.
    /// </summary>
    /// <param name="_parameters">Parameters for the update operation.</param>
    /// <param name="_updateHeader">Indicates whether to update the header.</param>
    public void update(
     anytype _parameters,
     NoYes _updateHeader)
    {
        next update(_parameters, _updateHeader);

        METInventTransferLine metInventTransferLine = this.metInventTransferLine();
        if (metInventTransferLine.RecId)
        {
            metInventTransferLine.updateUnitFields();
        }
    }
